#[cfg(before)] #[path="baseline/objects.rs"] mod objects;
#[cfg(not(before))] #[path="proposal/crates/weblabel-api/src/storage/objects.rs"] mod objects;
use std::{fs,os::windows::ffi::OsStrExt,path::PathBuf};
fn main(){let base=PathBuf::from(std::env::args().nth(1).unwrap());let base=base.join(if cfg!(before){"before"}else{"after"});let root=base.join("r".repeat(200-base.as_os_str().encode_wide().count()-1));let store=objects::ObjectStore::new(&root).unwrap();let bytes=b"consumer immutable owned bytes";let staged=store.stage_bytes("image.png",bytes).unwrap();let discarded=store.stage_bytes("discarded.png",b"discard this temporary").unwrap();drop(discarded);match staged.publish(){Err(e)=>{println!("publish_error={e:?} root_length={}",root.as_os_str().encode_wide().count());std::process::exit(1)},Ok(obj)=>{assert_eq!(fs::read(&obj.path).unwrap(),bytes);let duplicate=store.put_bytes("duplicate.png",bytes).unwrap();assert_eq!(duplicate.sha256,obj.sha256);let reopened=objects::ObjectStore::new(&root).unwrap();assert_eq!(fs::read(reopened.path_for_hash(&obj.sha256).unwrap()).unwrap(),bytes);let mut files=0;for shard in fs::read_dir(store.root()).unwrap(){for dir in fs::read_dir(shard.unwrap().path()).unwrap(){for file in fs::read_dir(dir.unwrap().path()).unwrap(){assert!(!file.unwrap().file_name().to_string_lossy().starts_with(".tmp-"));files+=1}}}assert_eq!(files,1);println!("PASS original_root_length={} published_length={} bytes={} duplicate_sha={} read_after_reopen=true discarded_stage_absent=true file_count={files}",root.as_os_str().encode_wide().count(),obj.path.as_os_str().encode_wide().count(),obj.size_bytes,obj.sha256)}}}
